DROP TABLE IF EXISTS `weibo_posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `weibo_posts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `weibo_id` varchar(32) NOT NULL COMMENT '微博数字ID（唯一）',
  `user_id` varchar(50) NOT NULL COMMENT '作者用户ID',
  `username` varchar(100) DEFAULT NULL COMMENT '作者昵称（冗余）',
  `content` text COMMENT '微博正文（清洗后纯文本）',
  `content_raw` text COMMENT '微博正文原始HTML（溯源用）',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间（API created_at解析）',
  `like_count` bigint NOT NULL DEFAULT '0' COMMENT '点赞数',
  `comment_count` bigint NOT NULL DEFAULT '0' COMMENT '评论数',
  `repost_count` bigint NOT NULL DEFAULT '0' COMMENT '转发数',
  `url` varchar(500) DEFAULT NULL COMMENT '微博链接',
  `source` varchar(50) DEFAULT NULL COMMENT '采集来源 keyword/account',
  `topic` varchar(100) DEFAULT NULL COMMENT '命中关键词/话题',
  `dataset_type` varchar(32) NOT NULL DEFAULT 'ai_industry' COMMENT '数据集类型: ai_industry=AI行业 / brand_monitor=企业品牌 / general_hotspot=全网热点',
  `crawl_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '爬取时间',
  `comment_crawl_status` tinyint NOT NULL DEFAULT '0' COMMENT '评论采集状态 0待采集 1已完成 2失败',
  `comment_crawl_time` datetime DEFAULT NULL COMMENT '评论最近采集时间',
  `comment_crawl_count` int NOT NULL DEFAULT '0' COMMENT '最近一次采集到的评论数',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_weibo_id` (`weibo_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_publish_time` (`publish_time`),
  KEY `idx_username` (`username`),
  KEY `idx_topic` (`topic`),
  KEY `idx_comment_crawl_status` (`comment_crawl_status`),
  KEY `idx_comment_crawl_time` (`comment_crawl_time`),
  KEY `idx_dataset_type` (`dataset_type`)
) ENGINE=InnoDB AUTO_INCREMENT=3634 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='微博帖子表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `weibo_posts` DISABLE KEYS */;
